        references_by_source = {
            'literal': [''], 'context': [alias for alias, key in fact_aliases.items() if self.context['facts'][key]['kind'] != 'choice'],
            'history': [alias for alias, key in ref_aliases.items() if not key.startswith('database:')],
            'database': [alias for alias, key in ref_aliases.items() if key.startswith('database:')],
            'code': list(code_aliases), 'ui': sorted({k for site in sites for k in site['body_fields']
                                                   if any(k in self.project.request_fields(mid) for mid in candidates)}),
            'fresh': [''], 'unknown': ['']}
        for source, allowed in references_by_source.items():
            if not allowed:
                continue
            variant = deepcopy(base_binding)
            variant['properties']['source'] = {'const': source}
            variant['properties']['reference'] = {'enum': allowed}
            if source in ('context', 'history', 'database', 'code', 'ui', 'fresh', 'unknown'):
                variant['properties']['value'] = {'type': 'null'}
            variants.append(variant)
        item['bindings']['items'] = {'oneOf': variants}
        payload['binding_sources'] = references_by_source
        task = (
            'Choose executable HTTP requests from the supplied contracts. A hypothesis must match the action. '
            'Return one hypothesis unless the intent is truly ambiguous; never list nonmatching candidates. '
            'Each binding has parameter, source, reference, value, quote. Explicitly bind stated booleans, including negations. '
            'Literal: reference="", value is an explicit value in current action/scenario text, quote is exact. '
            'Example: action "read document Z9" gives '
            '{"parameter":"key","source":"literal","reference":"","value":"Z9","quote":"Z9"}. '
            'Reference sources: value=null, reference is one allowed alias in binding_sources. '
            'Example: if references contains R7 with path history[1].result.key, a prior-object key uses '
            '{"parameter":"key","source":"history","reference":"R7","value":null,"quote":""}. '
            'For first/second/previous/newly created objects, select the matching returned object in prior_results '
            'by creation order. If no matching prior result exists, use source="unknown", reference="", value=null. '
            'Use context aliases for defaults, code aliases for enums/options/constants, database aliases for provided records, '
            'ui for fields computable from a selected UI request. Never turn a prior result or database value into a literal. '
            'fresh is only for explicitly requested new input that was not specified. '
            'Use actual server parameter/DTO names. Respect roles and dependencies. Give one short sentence as reason. '
            'Do not invent credentials, dates, IDs, enum values or successful execution results.')
        try:
            proposal = deepcopy(prepared_proposal) if prepared_proposal is not None else self.parser.propose(
                task, payload, schema)
        except (ValueError, KeyError) as exc:
            return [], {'candidates': candidates, 'proposal': None,
                        'unresolved': ['Local parser could not produce a supported request: ' + str(exc)]}
        raw_proposal = deepcopy(proposal)
        accepted, rejected = [], list(proposal['unresolved'])
        for hypothesis in proposal['hypotheses']:
            mid = handler_aliases.get(hypothesis['handler'], hypothesis['handler'])
            if mid not in candidates:
                rejected.append('Rejected handler not present in retrieved source contracts')
                continue
            site_id = ui_aliases.get(hypothesis['ui_site'], hypothesis['ui_site'])
            site = self.frontend.sites.get(site_id)
            if hypothesis['ui_site'] and (site is None or mid not in site['handlers']):
                rejected.append('Rejected UI site not linked to the selected handler')
                continue
            path_state = deepcopy(state)
            params, evidence, problems = {}, {}, []
            fields = self.project.request_fields(mid)
            if site:
                self.frontend.enter(site, path_state)
                for key, expression in site['body_fields'].items():
                    if key in fields:
                        value = self.frontend.evaluate(expression, path_state, definitions=site['definitions'])
                        if value is not U:
                            params[key] = value
                            evidence[key] = {'source': 'ui', 'reference': site['id'], 'expression': expression}
                url = self.frontend.evaluate(site['url'], path_state, definitions=site['definitions'])
                if isinstance(url, str):
                    from .engine import Engine
                    params.update(Engine(self.project, path_state).path_parameters(mid, url))
            bound = set()
            for binding in hypothesis['bindings']:
                key = binding['parameter']
                if key not in fields or key in bound:
                    problems.append('Rejected unknown or duplicate parameter: ' + key)
                    continue
                bound.add(key)
                source, ref, quote = binding['source'], binding['reference'], binding['quote']
                if source == 'context':
                    ref = fact_aliases.get(ref, ref)
                elif source in ('history', 'database'):
                    ref = ref_aliases.get(ref, ref)
                elif source == 'code':
                    ref = code_aliases.get(ref, ref)
                binding['reference'] = ref
                value = U
                if source == 'literal':
                    literal_value = binding['value']
                    if fields[key].split('.')[-1] in ('boolean', 'Boolean'):
                        from .engine import Engine
                        if isinstance(literal_value, str):
                            literal_value = {'enabled': True, 'disabled': False, 'yes': True, 'no': False}.get(literal_value.lower(), literal_value)
                        literal_value = Engine.coerce(literal_value, fields[key])
                    checked_quote = literal_quote(literal_value, quote, action + '\n' + scenario_text)
                    if checked_quote:
                        value = literal_value
                        if checked_quote != quote:
                            binding['model_quote'] = quote
                            binding['quote'] = checked_quote
                            binding['normalization'] = 'canonical boolean grounded in an exact input phrase'
                elif source == 'context':
                    fact = self.context['facts'].get(ref)
                    if fact and fact['kind'] != 'choice':
                        value = deepcopy(fact['value'])
                elif source in ('history', 'database'):
                    value = deepcopy(refs.get(ref, U))
                elif source == 'code':
                    value = deepcopy(values.get(ref, U))
                elif source == 'ui' and site:
                    expression = site['body_fields'].get(ref or key)
                    if expression:
                        value = self.frontend.evaluate(expression, path_state, definitions=site['definitions'])
                elif source == 'fresh' and quote and quote in action and re.search(r'\bnew\b|\bcreate\b|\bregister\b|\badd\b', action, re.I):
                    value = path_state.fresh_input(key, fields[key])
                if value is not U:
                    from .engine import Engine
                    value = Engine.coerce(value, fields[key])
                if value is U:
                    if source != 'unknown':
                        problems.append('Unsupported parameter binding: ' + key + ' from ' + source)
                    params.pop(key, None)
                else:
                    params[key] = value
                evidence[key] = {**binding, 'resolved': value is not U}
            # No default values are copied from another request or method name.
            missing = [key for key, typ in fields.items() if key not in params and 'Header' not in typ]
            if site:
                for key, expression in site['body_fields'].items():
                    if key not in params:
                        continue
                    form = re.fullmatch(r'(?:this|that)\.(\w+)', expression)
                    dom = re.fullmatch(r'\$\(([\"\'].*?[\"\'])\)\.val\(\)', expression)
                    if form:
                        path_state.browser['form'][form[1]] = deepcopy(params[key])
                    elif dom:
                        path_state.browser['dom'][dom[1][1:-1]] = deepcopy(params[key])
            accepted.append({'entry': mid, 'params': params, 'state': path_state, 'site': site,
                             'bindings': evidence, 'reason': hypothesis['reason'],
                             'unresolved': problems + ['Unknown input: ' + k for k in missing]})
        # Prepared templates use stable actual references, not aliases whose numbering changes with path state.
        for hypothesis in proposal['hypotheses']:
            hypothesis['handler'] = handler_aliases.get(hypothesis['handler'], hypothesis['handler'])
            hypothesis['ui_site'] = ui_aliases.get(hypothesis['ui_site'], hypothesis['ui_site'])
        repair_errors = rejected + [problem for choice in accepted for problem in choice['unresolved']
            if not problem.startswith('Unknown input: ') or choice['bindings'].get(problem.split(': ', 1)[-1], {}).get('source') != 'unknown']
        if prepared_proposal is None and repair_errors:
            try:
                repaired = self.parser.propose(task + ' Correct the previous proposal using the validation errors. '
                    'Use a supported reference or explicit unknown for rejected bindings. Do not repeat invalid quotes.',
                    {**payload, 'previous_proposal': raw_proposal, 'validation_errors': repair_errors}, schema)
                accepted, detail = self.step(action, state, scenario_text, prepared_proposal=repaired)
                detail['repairs'] = [{'previous_proposal': raw_proposal, 'validation_errors': repair_errors}]
                return accepted, detail
            except (ValueError, KeyError):
                pass
        return accepted, {'candidates': candidates, 'proposal': proposal, 'raw_proposal': raw_proposal,
                          'unresolved': rejected}

"""Deterministic source-contract retrieval and evidence-bearing request bindings."""
from copy import deepcopy
import re

from baseline_closure import BM25
from baseline_nlp import ntoks
from .context import context_spans, dates_in
from .engine import Engine
from .grounding import references
from .project import text
from .state import U


STOP = set('the a an with without and or for of to from on in by this that their they first new one '
           'controller service api http org springframework request response java string'.split())
# Language-level synonyms only; project entities, routes and enum values come from source.
VERBS = [set('get find query lookup search read view open show list refresh inspect fetch'.split()),
         set('create add insert register save book reserve'.split()),
         set('delete remove erase'.split()), set('update modify change edit'.split()),
         set('login signin authenticate'.split())]
VERBS[0].update(('check', 'browse', 'look'))


def tokens(value):
    words = ntoks(re.sub(r'\blog\s+in\b', 'login', str(value), flags=re.I))
    output = [word for word in words if word not in STOP]
    return output


def intent(value):
    value = re.sub(r'^as\b.*?,\s*|^(?:try\s+to|please)\s+', '', value, flags=re.I)
    words = tokens(value)
    return next((i for i, group in enumerate(VERBS) if words and words[0] in group), None)


def normalized(value):
    return re.sub(r'[^a-z0-9]', '', value.lower())


def read_static_context(raw):
    spans, limited, credentials = context_spans(raw)
    facts = {}
    clock = None
    for pair in credentials:
        for name, ref in pair.items():
            span = spans[ref]
            facts[name] = {**span, 'kind': 'credential', 'reference': ref}
    for ref, span in spans.items():
        if span['type'] != 'date':
            continue
        label = span.get('label', '')
        if re.search(r'\b(?:system\s+clock|current\s+(?:date|time)|today)\b', label, re.I):
            clock = dates_in(str(span['value']))[0]
        else:
            facts.setdefault('request_date', {**span, 'kind': 'default', 'reference': ref})
    for key, value in raw.items() if isinstance(raw, dict) else []:
        if isinstance(value, (bool, int, float)) or (isinstance(value, str) and len(value.split()) == 1):
            facts[str(key)] = {'value': value, 'kind': 'default', 'quote': str(value), 'source': str(key)}
    unresolved = ['System clock is unknown'] if clock is None else []
    if limited:
        unresolved.append('Context span budget exceeded')
    return {'facts': facts, 'clock': clock, 'unresolved': unresolved, 'raw': deepcopy(raw)}


class ContractIndex:
    def __init__(self, project, frontend):
        self.project, self.frontend = project, frontend
        self.contracts, docs, extra_docs = {}, {}, {}
        for mid, verb, route in project.ix.handlers:
            sites = [s for s in frontend.sites.values() if mid in s['handlers']] or [None]
            for site in sites:
                key = mid + '|' + (site['id'] if site else '')
                name = project.methods[mid]['name']
                owner = project.nodes[project.methods[mid]['owner']]['fqn'].split('.')[-1]
                primary = tokens(name + ' ' + owner + ' ' + ' '.join(route))
                source = text(project.ast.get(mid))[:1800]
                ui = (site['source'][:1000] + ' ' + site['file']) if site else ''
                docs[key] = primary
                extra_docs[key] = tokens(source) + tokens(ui)
                self.contracts[key] = {'entry': mid, 'site': site, 'verb': verb,
                                       'route': route, 'primary': primary, 'intent': intent(name),
                                       'source_words': set(tokens(source + ' ' + ui))}
        self.bm25 = BM25(docs)
        self.extra = BM25(extra_docs)

    def rank(self, action):
        # Weight the direct object before qualifications about related entities.
        focus = re.split(r'\b(?:for|with|without|from|departing|filtered|on|onto)\b', action, 1, flags=re.I)[0]
        query = tokens(focus)
        wanted = intent(action)
        verb_words = {word for group in VERBS for word in group}
        objects = [word for word in query if word not in verb_words]
        base = dict((key, score) for score, key in self.bm25.rank(query))
        extra = dict((key, score) for score, key in self.extra.rank(query))
        result = []
        for key in set(base) | set(extra):
            contract = self.contracts[key]
            score = base.get(key, 0) + 0.15 * extra.get(key, 0)
            primary = set(contract['primary'])
            score += 2 * sum(self.bm25.idf.get(word, 0) for word in objects if word in primary)
            actual = contract['intent']
            if wanted is not None:
                score *= 1.8 if actual == wanted else 0.12 if actual is not None else 0.6
            elif query:
                score *= 2 if query[0] in primary else 0.35
            result.append((score, key, contract))
        return sorted(result, key=lambda item: (-item[0], item[1]))

    def candidates(self, action, limit=6):
        return list(dict.fromkeys(c['entry'] for _, _, c in self.rank(action)))[:limit]


def explicit_value(action, key, typ):
    words = re.findall(r'[a-z0-9]+', re.sub(r'([a-z0-9])([A-Z])', r'\1 \2', key).lower())
    label = r'[ _-]*'.join(re.escape(word) for word in words)
    # Match field labels, never positional bare numbers that could be dates or ordinals.
    patterns = [r'\b' + re.escape(key) + r'\b\s*(?:is|=|:)?\s*[\"\']([^\"\']+)[\"\']',
                r'\b' + label + r'\b\s*(?:is|=|:)?\s*([\w@.+-]+)'] if label else []
    for pattern in patterns:
        match = re.search(pattern, action, re.I)
        if match and match[1].lower() not in {'and', 'or', 'with', 'of', 'for', 'to', 'from'}:
            value = Engine.coerce(match[1], typ)
            if typ.split('.')[-1] in ('String', 'UUID') or value is not U:
                return value, match[0]
    if typ.split('.')[-1] in ('boolean', 'Boolean'):
        field = r'\b' + label + r'\b'
        for match in re.finditer(field, action, re.I):
            before = action[max(0, match.start() - 24):match.start()]
            if re.search(r'\b(?:without|no|not|disable)\s*$', before, re.I):
                return False, before + match[0]
            after = action[match.end():match.end() + 16]
            if re.match(r'\s*(?:is\s+)?(?:false|disabled)\b', after, re.I):
                return False, match[0] + after
            if re.search(r'\b(?:with|enable)\s*$', before, re.I) or re.match(r'\s*(?:is\s+)?(?:true|enabled)\b', after, re.I):
                return True, before + match[0] + after
    return U, ''


class ContractGrounder:
    def __init__(self, project, frontend, retrieval, parser, context):
        self.project, self.frontend, self.index, self.context = project, frontend, retrieval, context

    def step(self, action, state, scenario_text='', prepared_proposal=None):
        ranked = self.index.rank(action)
        candidates = [c['entry'] for _, _, c in ranked[:6]]
        detail = {'candidates': candidates, 'ranking': [
            {'entry': c['entry'], 'ui_site': c['site']['id'] if c['site'] else None, 'score': score}
            for score, _, c in ranked[:6]], 'proposal': {'hypotheses': []}, 'unresolved': []}
        if not ranked:
            detail['unresolved'] = ['No lexical evidence for a source request']
            return [], detail
        score, _, contract = ranked[0]
        mid, site = contract['entry'], contract['site']
        path_state = deepcopy(state)
        fields = self.project.request_fields(mid)
        params, bindings = {}, {}

        def bind(key, value, source, reference, quote=''):
            if value is not U:
                params[key] = Engine.coerce(deepcopy(value), fields[key])
                bindings[key] = {'source': source, 'reference': reference, 'quote': quote,
                                 'resolved': params[key] is not U}

        if site:
            self.frontend.enter(site, path_state)
            for key, expression in site['body_fields'].items():
                if key in fields:
                    bind(key, self.frontend.evaluate(expression, path_state, definitions=site['definitions']),
                         'ui', site['id'] + ':' + expression)
            url = self.frontend.evaluate(site['url'], path_state, definitions=site['definitions'])
            if isinstance(url, str):
                for key, value in Engine(self.project, path_state).path_parameters(mid, url).items():
                    if key in fields:
                        bind(key, value, 'ui', site['id'] + ':url')
        for key, typ in fields.items():
            value, quote = explicit_value(action, key, typ)
            if value is not U:
                bind(key, value, 'literal', 'action', quote)
                continue
            for name, fact in self.context['facts'].items():
                if normalized(name) == normalized(key):
                    bind(key, fact['value'], 'context', name, fact.get('quote', ''))
            if key in params:
                continue
            date_fields = [name for name in fields if set(tokens(name)) & {'date', 'time'}]
            if len(date_fields) == 1 and key in date_fields:
                dates = dates_in(action)
                if dates:
                    bind(key, dates[0].isoformat(), 'literal', 'action', str(dates[0].date()))
                elif 'request_date' in self.context['facts']:
                    bind(key, self.context['facts']['request_date']['value'], 'context', 'request_date')
            target = self.project.resolve_type(typ, self.project.methods[mid]['module'])
            enum = self.project.enum_members.get(target, [])
            matches = [e for e in enum if set(tokens(e.rsplit('.', 1)[-1])) <= set(tokens(action))]
            if len(matches) == 1:
                bind(key, self.project.enum_objects.get(matches[0], U), 'code', matches[0])
            # UI options keep the association to their actual form field.
            if site and key in site['body_fields']:
                expression = site['body_fields'][key]
                options = [o for o in site['options'] if o['control'] and o['control'] in expression
                           and set(tokens(o['label'])) and set(tokens(o['label'])) <= set(tokens(action))]
                if len(options) == 1:
                    bind(key, options[0]['value'], 'ui', site['id'] + ':option', options[0]['label'])
            if key in params:
                continue
            for i in range(len(state.history) - 1, -1, -1):
                refs = references(state.history[i]['result'], 'history[' + str(i) + '].result')
                matches = [(ref, value) for ref, value in refs.items()
                           if normalized(ref.rsplit('.', 1)[-1]) == normalized(key) and value is not U]
                if len(matches) == 1:
                    bind(key, matches[0][1], 'history', matches[0][0])
                    break
        problems = ['Unknown input: ' + key for key, typ in fields.items()
                    if key not in params and 'Header' not in typ]
        # Lexical ranking is evidence for a hypothesis, never proof of user intent.
        problems.append('Request selected by lexical evidence; intent is not independently confirmed')
        return [{'entry': mid, 'site': site, 'state': path_state, 'params': params, 'bindings': bindings,
                 'reason': 'Highest BM25 source/UI contract score: ' + str(score), 'unresolved': problems}], detail

"""Rank source-derived handler contracts by BM25 and dense reciprocal ranks."""
import hashlib
import json
from pathlib import Path
from baseline_closure import BM25
from baseline_nlp import ntoks, front_files
from .project import text


def fingerprint(project):
    digest = hashlib.sha256(json.dumps(project.skeleton, sort_keys=True).encode())
    for file, source in sorted(project.sources.items()):
        digest.update(file.encode())
        digest.update(source)
    for file in sorted(front_files(str(project.root))):
        digest.update(str(Path(file).relative_to(project.root)).encode())
        digest.update(Path(file).read_bytes())
    return digest.hexdigest()


class Retrieval:
    def __init__(self, project, frontend):
        self.documents = {}
        for mid, _, route in project.ix.handlers:
            meta = project.methods[mid]
            sites = [site for site in frontend.sites.values() if mid in site['handlers']]
            source = text(project.ast.get(mid))
            self.documents[mid] = '\n'.join([meta['name'], meta['module'], '/'.join(route),
                                             str(project.request_fields(mid)), source[:1800],
                                             *[site['labels'][:700] + '\n' + site['source'][:1200] for site in sites[:4]]])
        self.ids = sorted(self.documents)
        self.bm25 = BM25({mid: ntoks(doc) for mid, doc in self.documents.items()})
        self.rankings = {}

    def prepare(self, actions, encoder):
        import numpy as np
        # Fixed-size overlapping text windows prevent long files from replacing method boundaries.
        chunks, owners = [], []
        for mid in self.ids:
            words = self.documents[mid].split()
            for start in range(0, max(1, len(words)), 220):
                chunks.append(' '.join(words[start:start + 280]))
                owners.append(mid)
        vectors = encoder.encode(chunks)
        queries = sorted(set(actions))
        query_vectors = encoder.encode(queries) if queries else np.zeros((0, vectors.shape[1]))
        for query, query_vector in zip(queries, query_vectors):
            dense_scores = {}
            for mid, score in zip(owners, vectors @ query_vector):
                dense_scores[mid] = max(dense_scores.get(mid, -1), float(score))
            dense = sorted(dense_scores, key=lambda mid: (-dense_scores[mid], mid))
            lexical = [mid for _, mid in self.bm25.rank(ntoks(query))]
            scores = {mid: 0.0 for mid in self.ids}
            for ranking in (dense, lexical):
                for rank, mid in enumerate(ranking):
                    scores[mid] += 1 / (60 + rank + 1)
            hybrid = sorted(scores, key=lambda mid: (-scores[mid], mid))
            self.rankings[query] = {'hybrid': hybrid[:20], 'bm25': lexical[:20], 'dense': dense[:20],
                                    'scores': {mid: scores[mid] for mid in hybrid[:20]}}
        return self.rankings

    def save(self, path, project):
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_text(json.dumps({'schema': 1, 'recipe': 'BM25+BGE-M3-dense/RRF60/windows280-overlap60/max_seq512',
                                         'fingerprint': fingerprint(project), 'rankings': self.rankings}, indent=2) + '\n')

    def load(self, path, project):
        obj = json.loads(Path(path).read_text())
        if obj.get('schema') != 1 or obj['fingerprint'] != fingerprint(project):
            raise ValueError('Retrieval index does not match source and skeleton')
        self.rankings = obj['rankings']

    def candidates(self, action, limit=6):
        if action not in self.rankings:
            raise ValueError('Unindexed action: run prepare_index.py for the new scenarios')
        return self.rankings[action]['hybrid'][:limit]

